type Component = Props => Html

def withLogging(component: Component): Component =        // Component => Component
  props => { log.info("render"); component(props) }

def withAuth(role: String)(component: Component): Component =
  props => if (allowed(role, props)) component(props) else Forbidden

val Page = withLogging(withAuth("admin")(PricePanel))     // applied once
